using System;
using System.Reflection;
using GameFoundation.Save;
using NUnit.Framework;
using UnityEngine;
namespace AllSorted.Tests
{
    public sealed class PrelevelBoosterTests
    {
        private sealed class Store : ISaveStore {
            public readonly MemorySaveStore Inner=new MemorySaveStore();public bool Fail;
            public bool TryRead(string k,out string v){return Inner.TryRead(k,out v);}public bool TryReadBackup(string k,out string v){return Inner.TryReadBackup(k,out v);}
            public void Write(string k,string v){if(Fail)throw new System.IO.IOException("test entry save failure");Inner.Write(k,v);}public void Restore(string k,string v){Inner.Restore(k,v);}public void Delete(string k){Inner.Delete(k);}
        }
        private static T Call<T>(object target,string name,params object[] args){var m=target.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);Assert.IsNotNull(m,"Missing "+name);return (T)m.Invoke(target,args);}
        [TestCase(0)][TestCase(1)] public void PurchaseSavesExactly1600ForThreeOfOnlyTheEmptyEntryBooster(int index){var s=new Store();var c=new WalletTestClock();var w=new SortWalletLedger(s,c);for(int i=0;i<3;i++)Call<bool>(w,"SpendEntryCharges",1<<index);Assert.IsTrue(Call<bool>(w,"BuyEntryBooster",index));Assert.AreEqual(0,w.Coins);Assert.AreEqual(3,w.GetEntryCharges(index));Assert.AreEqual(3,w.GetEntryCharges(1-index));Assert.AreEqual(3,w.GetCharges(SortBooster.Vacuum));var reload=new SortWalletLedger(s,c);Assert.AreEqual(0,reload.Coins);Assert.AreEqual(3,reload.GetEntryCharges(index));Assert.IsFalse(Call<bool>(w,"BuyEntryBooster",index));}
        [Test] public void FailedEntryPurchaseSaveIsAtomicAndRetryable(){var s=new Store();var w=new SortWalletLedger(s,new WalletTestClock());for(int i=0;i<3;i++)w.SpendEntryCharges(1);s.Fail=true;Assert.IsFalse(Call<bool>(w,"BuyEntryBooster",0));Assert.AreEqual(1600,w.Coins);Assert.AreEqual(0,w.GetEntryCharges(0));s.Fail=false;Assert.IsTrue(Call<bool>(w,"BuyEntryBooster",0));Assert.AreEqual(0,w.Coins);Assert.AreEqual(3,w.GetEntryCharges(0));}
        [TestCase(-1)][TestCase(2)] public void InvalidEntryPurchaseDoesNotChangeWallet(int index){var w=new SortWalletLedger(new MemorySaveStore(),new WalletTestClock());Assert.IsFalse(Call<bool>(w,"BuyEntryBooster",index));Assert.AreEqual(1600,w.Coins);}
        [Test] public void EntryPurchaseRequiresEmptyStockAndEnoughCoins(){var w=new SortWalletLedger(new MemorySaveStore(),new WalletTestClock());Assert.IsFalse(Call<bool>(w,"BuyEntryBooster",0));for(int i=0;i<3;i++)w.SpendEntryCharges(3);Assert.IsTrue(Call<bool>(w,"BuyEntryBooster",0));Assert.IsFalse(Call<bool>(w,"BuyEntryBooster",1));Assert.AreEqual(0,w.GetEntryCharges(1));}
        [Test] public void BothChargesStartAtThreeGrantIndependentlyAndPersist(){var s=new Store();var c=new WalletTestClock();var w=new SortWalletLedger(s,c);Assert.AreEqual(3,Call<int>(w,"GetEntryCharges",0));Assert.IsTrue(Call<bool>(w,"AddEntryCharge",0));var reload=new SortWalletLedger(s,c);Assert.AreEqual(4,Call<int>(reload,"GetEntryCharges",0));Assert.AreEqual(3,Call<int>(reload,"GetEntryCharges",1));Assert.AreEqual(1600,reload.Coins);Assert.AreEqual(5,reload.Energy);}
        [Test] public void SelectedChargesSpendAtomicallyAndNeverBelowZero(){var s=new Store();var c=new WalletTestClock();var w=new SortWalletLedger(s,c);for(int i=0;i<3;i++)Assert.IsTrue(Call<bool>(w,"SpendEntryCharges",3));Assert.IsFalse(Call<bool>(w,"SpendEntryCharges",3));Assert.AreEqual(0,Call<int>(w,"GetEntryCharges",0));Assert.AreEqual(0,Call<int>(new SortWalletLedger(s,c),"GetEntryCharges",1));}
        [Test] public void FailedSaveDoesNotGrantOrSpendEitherCharge(){var s=new Store();var w=new SortWalletLedger(s,new WalletTestClock());s.Fail=true;Assert.IsFalse(Call<bool>(w,"SpendEntryCharges",3));Assert.IsFalse(Call<bool>(w,"AddEntryCharge",0));Assert.AreEqual(3,Call<int>(w,"GetEntryCharges",0));Assert.AreEqual(3,Call<int>(w,"GetEntryCharges",1));s.Fail=false;Assert.IsTrue(Call<bool>(w,"SpendEntryCharges",3));}
        [TestCase(-1)][TestCase(4)] public void InvalidMasksNeverMutateStock(int mask){var w=new SortWalletLedger(new MemorySaveStore(),new WalletTestClock());Assert.IsFalse(Call<bool>(w,"SpendEntryCharges",mask));Assert.AreEqual(3,Call<int>(w,"GetEntryCharges",0));}
        [TestCase(1)][TestCase(2)] public void LegacyWalletGetsThreeWithoutChangingOldBalances(int version){var s=new Store();var c=new WalletTestClock();string payload="{\"Coins\":7777,\"Energy\":4,\"NextRecoveryUtcTicks\":"+c.Now.AddSeconds(500).UtcTicks+",\"LastSeenUtcTicks\":"+c.Now.UtcTicks+(version==2?",\"BoosterCharges\":[0,1,2,3]}":"}");s.Write(SortWalletLedger.SaveSlot,JsonUtility.ToJson(new SaveEnvelope{Version=version,Payload=payload,Checksum=SaveChecksum.Compute(version,payload)}));var w=new SortWalletLedger(s,c);Assert.IsTrue(w.Writable);Assert.AreEqual(7777,w.Coins);Assert.AreEqual(4,w.Energy);Assert.AreEqual(500,w.RecoverySeconds);Assert.AreEqual(3,Call<int>(w,"GetEntryCharges",0));if(version==2)Assert.AreEqual(0,w.GetCharges(SortBooster.Vacuum));}
        [TestCase(1)][TestCase(2)][TestCase(3)] public void StrongVacuumRemovesThreeSetsAndTimeAddsExactlyThirty(int level){var normal=PrototypeLevel.Create(level);var b=PrototypeLevel.Create(level);Assert.IsTrue(Call<bool>(b,"TryApplyEntryBoosters",3,new System.Random(12)));Assert.AreEqual(normal.RemainingSeconds+30,b.RemainingSeconds);Assert.GreaterOrEqual(normal.RemainingCount-b.RemainingCount,9);Assert.GreaterOrEqual(b.Matches-normal.Matches,3);}
        [Test] public void NoSelectionLeavesBoardUnchanged(){var b=PrototypeLevel.Create(1);int n=b.RemainingCount;float t=b.RemainingSeconds;Assert.IsTrue(Call<bool>(b,"TryApplyEntryBoosters",0,new System.Random(1)));Assert.AreEqual(n,b.RemainingCount);Assert.AreEqual(t,b.RemainingSeconds);}
    }
}
